def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    import re

    token_re = re.compile(
        r"\s*([A-Z](?:[1-9][0-9]?)(?:\s*:\s*[A-Z](?:[1-9][0-9]?))?"
        r"|SUM|MIN|MAX|IF|[0-9]+|<>|<=|>=|[+\-*/(),=<>])"
    )
    precedence = {
        "=": 1, "<>": 1, "<": 1, "<=": 1, ">": 1, ">=": 1,
        "+": 2, "-": 2, "*": 3, "/": 3, "u-": 4,
    }
    values = {}
    active = set()

    def parse(formula):
        tokens = [match.group(1) for match in token_re.finditer(formula)]
        output = []
        operators = []
        expecting_operand = True
        i = 0

        def reduce_operator():
            op = operators.pop()
            if op == "u-":
                output.append(("unary", output.pop()))
            else:
                right = output.pop()
                left = output.pop()
                output.append(("binary", op, left, right))

        while i < len(tokens):
            token = tokens[i]

            if token in ("SUM", "MIN", "MAX", "IF"):
                operators.append(["(", token, 0])
                i += 2  # Skip the function name and its opening parenthesis.
                expecting_operand = True
                continue

            if token == "(":
                operators.append(["(", None, 0])
                expecting_operand = True
            elif token == ",":
                while isinstance(operators[-1], str):
                    reduce_operator()
                operators[-1][2] += 1
                expecting_operand = True
            elif token == ")":
                while isinstance(operators[-1], str):
                    reduce_operator()
                _, function, commas = operators.pop()
                if function is not None:
                    count = commas + 1
                    args = output[-count:]
                    del output[-count:]
                    output.append(("function", function, args))
                expecting_operand = False
            elif token in precedence:
                op = "u-" if token == "-" and expecting_operand else token
                while (
                    operators
                    and isinstance(operators[-1], str)
                    and (
                        precedence[operators[-1]] > precedence[op]
                        or (
                            precedence[operators[-1]] == precedence[op]
                            and op != "u-"
                        )
                    )
                ):
                    reduce_operator()
                operators.append(op)
                expecting_operand = True
            elif token[0].isdigit():
                output.append(("number", int(token)))
                expecting_operand = False
            elif ":" in token:
                start, end = (part.strip() for part in token.split(":"))
                output.append(("range", start, end))
                expecting_operand = False
            else:
                output.append(("reference", token))
                expecting_operand = False

            i += 1

        while operators:
            reduce_operator()
        return output[0]

    def is_error(value):
        return isinstance(value, str)

    def range_nodes(start, end):
        first_col, last_col = sorted((ord(start[0]), ord(end[0])))
        first_row, last_row = sorted((int(start[1:]), int(end[1:])))
        for row in range(first_row, last_row + 1):
            for col in range(first_col, last_col + 1):
                name = chr(col) + str(row)
                if name in cells:
                    yield ("reference", name)

    def argument_nodes(args):
        for arg in args:
            if arg[0] == "range":
                yield from range_nodes(arg[1], arg[2])
            else:
                yield arg

    def evaluate(name):
        results = []
        tasks = [("cell", name)]

        while tasks:
            task = tasks.pop()
            kind = task[0]

            if kind == "cell":
                cell = task[1]
                if cell not in cells:
                    results.append(0)
                elif cell in values:
                    results.append(values[cell])
                elif cell in active:
                    results.append("#CYCLE!")
                else:
                    active.add(cell)
                    content = cells[cell]
                    tasks.append(("finish_cell", cell))
                    if content.startswith("="):
                        tasks.append(("eval", parse(content[1:])))
                    else:
                        results.append(int(content))

            elif kind == "finish_cell":
                cell = task[1]
                values[cell] = results[-1]
                active.remove(cell)

            elif kind == "eval":
                node = task[1]
                node_kind = node[0]
                if node_kind == "number":
                    results.append(node[1])
                elif node_kind == "reference":
                    tasks.append(("cell", node[1]))
                elif node_kind == "unary":
                    tasks.append(("unary",))
                    tasks.append(("eval", node[1]))
                elif node_kind == "binary":
                    tasks.append(("binary_left", node[1], node[3]))
                    tasks.append(("eval", node[2]))
                elif node_kind == "function":
                    function, args = node[1], node[2]
                    if function == "IF":
                        tasks.append(("if_condition", args[1], args[2]))
                        tasks.append(("eval", args[0]))
                    else:
                        tasks.append(("function_next", function, iter(argument_nodes(args)), None))

            elif kind == "unary":
                value = results.pop()
                results.append(value if is_error(value) else -value)

            elif kind == "binary_left":
                op, right_node = task[1], task[2]
                left = results.pop()
                if is_error(left):
                    results.append(left)
                else:
                    tasks.append(("binary_right", op, left))
                    tasks.append(("eval", right_node))

            elif kind == "binary_right":
                op, left = task[1], task[2]
                right = results.pop()
                if is_error(right):
                    results.append(right)
                elif op == "+":
                    results.append(left + right)
                elif op == "-":
                    results.append(left - right)
                elif op == "*":
                    results.append(left * right)
                elif op == "/":
                    if right == 0:
                        results.append("#DIV/0!")
                    else:
                        quotient = abs(left) // abs(right)
                        results.append(-quotient if (left < 0) != (right < 0) else quotient)
                elif op == "=":
                    results.append(left == right)
                elif op == "<>":
                    results.append(left != right)
                elif op == "<":
                    results.append(left < right)
                elif op == "<=":
                    results.append(left <= right)
                elif op == ">":
                    results.append(left > right)
                else:
                    results.append(left >= right)

            elif kind == "if_condition":
                condition = results.pop()
                if is_error(condition):
                    results.append(condition)
                else:
                    tasks.append(("eval", task[1] if condition else task[2]))

            elif kind == "function_next":
                function, nodes, accumulator = task[1:]
                node = next(nodes, None)
                if node is None:
                    results.append(0 if accumulator is None else accumulator)
                else:
                    tasks.append(("function_value", function, nodes, accumulator))
                    tasks.append(("eval", node))

            elif kind == "function_value":
                function, nodes, accumulator = task[1:]
                value = results.pop()
                if is_error(value):
                    results.append(value)
                else:
                    if accumulator is None:
                        accumulator = value
                    elif function == "SUM":
                        accumulator += value
                    elif function == "MIN":
                        accumulator = min(accumulator, value)
                    else:
                        accumulator = max(accumulator, value)
                    tasks.append(("function_next", function, nodes, accumulator))

        return results.pop()

    for name in cells:
        if name not in values:
            evaluate(name)

    return {name: values[name] for name in cells}
